import{_ as r,o as t,c as s,am as a}from"./chunks/framework.yj4qiWdr.js";const d=JSON.parse('{"title":"OSINT","description":"Méthode, ressources et commandes de recherche en sources ouvertes.","frontmatter":{"title":"OSINT","description":"Méthode, ressources et commandes de recherche en sources ouvertes.","aside":false,"prev":false,"next":false},"headers":[],"relativePath":"osint/index.md","filePath":"osint/index.md"}'),o={name:"osint/index.md"};function n(i,e,l,h,c,g){return t(),s("div",null,e[0]||(e[0]=[a('<h1 id="osint" tabindex="-1">OSINT <a class="header-anchor" href="#osint" aria-label="Permalink to &quot;OSINT&quot;">​</a></h1><p>Une bibliothèque pratique pour la recherche en sources ouvertes. Les outils sont classés selon la <strong>question à résoudre</strong>, pas selon leur popularité.</p><p><strong><a href="./cheatsheet">Cheatsheet OSINT - commandes à copier</a></strong></p><p>Choisis un point de départ : <strong>pseudonyme</strong>, <strong>e-mail</strong>, <strong>nom</strong>, <strong>domaine</strong>, <strong>image</strong> ou <strong>infrastructure</strong>. Les résultats se recoupent avant toute conclusion.</p><h2 id="recherche-web-et-dorks" tabindex="-1">Recherche Web et dorks <a class="header-anchor" href="#recherche-web-et-dorks" aria-label="Permalink to &quot;Recherche Web et dorks&quot;">​</a></h2><ul><li><strong><a href="https://www.google.com/" target="_blank" rel="noreferrer">Google</a></strong> - Requêtes avancées avec <code>site:</code>, <code>filetype:</code> et expressions exactes.</li><li><strong><a href="https://www.bing.com/" target="_blank" rel="noreferrer">Bing</a></strong> - Autre index pour comparer les résultats.</li><li><strong><a href="https://search.brave.com/" target="_blank" rel="noreferrer">Brave Search</a></strong> - Moteur complémentaire pour élargir la recherche.</li><li><strong><a href="https://www.qwant.com/" target="_blank" rel="noreferrer">Qwant</a></strong> - Moteur de recherche alternatif.</li><li><strong><a href="https://www.exploit-db.com/google-hacking-database" target="_blank" rel="noreferrer">Google Hacking Database</a></strong> - Exemples d&#39;opérateurs pour une reconnaissance autorisée.</li></ul><h2 id="pseudonymes-et-profils-publics" tabindex="-1">Pseudonymes et profils publics <a class="header-anchor" href="#pseudonymes-et-profils-publics" aria-label="Permalink to &quot;Pseudonymes et profils publics&quot;">​</a></h2><ul><li><strong><a href="https://github.com/sherlock-project/sherlock" target="_blank" rel="noreferrer">Sherlock</a></strong> - Rechercher les comptes liés à un pseudonyme.</li><li><strong><a href="https://github.com/soxoj/maigret" target="_blank" rel="noreferrer">Maigret</a></strong> - Croiser les profils publics et produire un rapport.</li><li><strong><a href="https://github.com/WebBreacher/WhatsMyName" target="_blank" rel="noreferrer">WhatsMyName</a></strong> - Vérifier des pseudonymes sur des plateformes.</li><li><strong><a href="https://github.com/qeeqbox/social-analyzer" target="_blank" rel="noreferrer">Social Analyzer</a></strong> - Compléter l&#39;analyse des profils sociaux publics.</li><li><strong><a href="https://www.reddit.com/search/" target="_blank" rel="noreferrer">Reddit Search</a></strong> - Retrouver des publications et commentaires publics.</li><li><strong><a href="https://x.com/search-advanced" target="_blank" rel="noreferrer">X - Recherche avancée</a></strong> - Combiner mots-clés, comptes et périodes lorsque la recherche est disponible.</li></ul><h2 id="e-mails-et-exposition" tabindex="-1">E-mails et exposition <a class="header-anchor" href="#e-mails-et-exposition" aria-label="Permalink to &quot;E-mails et exposition&quot;">​</a></h2><ul><li><strong><a href="https://github.com/megadose/holehe" target="_blank" rel="noreferrer">Holehe</a></strong> - Rechercher des indices d&#39;inscription à partir d&#39;un e-mail.</li><li><strong><a href="https://haveibeenpwned.com/" target="_blank" rel="noreferrer">Have I Been Pwned</a></strong> - Vérifier l&#39;apparition d&#39;un e-mail dans des incidents documentés.</li><li><strong><a href="https://emailrep.io/" target="_blank" rel="noreferrer">EmailRep</a></strong> - Consulter des indicateurs de réputation d&#39;une adresse.</li><li><strong><a href="https://hunter.io/" target="_blank" rel="noreferrer">Hunter</a></strong> - Rechercher des adresses et formats d&#39;e-mails professionnels publics.</li></ul><h2 id="domaines-dns-et-sous-domaines" tabindex="-1">Domaines, DNS et sous-domaines <a class="header-anchor" href="#domaines-dns-et-sous-domaines" aria-label="Permalink to &quot;Domaines, DNS et sous-domaines&quot;">​</a></h2><ul><li><strong><a href="https://github.com/laramies/theHarvester" target="_blank" rel="noreferrer">theHarvester</a></strong> - Collecter sous-domaines, e-mails, URL et indices publics.</li><li><strong><a href="https://crt.sh/" target="_blank" rel="noreferrer">crt.sh</a></strong> - Explorer les noms figurant dans les certificats publics.</li><li><strong><a href="https://github.com/projectdiscovery/subfinder" target="_blank" rel="noreferrer">Subfinder</a></strong> - Rassembler des sous-domaines à partir de sources passives.</li><li><strong><a href="https://github.com/owasp-amass/amass" target="_blank" rel="noreferrer">Amass</a></strong> - Cartographier la surface d&#39;exposition d&#39;un domaine.</li><li><strong><a href="https://securitytrails.com/dns-trails" target="_blank" rel="noreferrer">SecurityTrails</a></strong> - Consulter des données DNS et leurs évolutions.</li><li><strong><a href="https://bgp.tools/" target="_blank" rel="noreferrer">BGP.tools</a></strong> - Identifier les annonces BGP et les réseaux associés.</li><li><strong><a href="https://lookup.icann.org/" target="_blank" rel="noreferrer">ICANN Lookup</a></strong> - Consulter les informations d&#39;enregistrement disponibles.</li></ul><h2 id="infrastructure-et-cybermenaces" tabindex="-1">Infrastructure et cybermenaces <a class="header-anchor" href="#infrastructure-et-cybermenaces" aria-label="Permalink to &quot;Infrastructure et cybermenaces&quot;">​</a></h2><ul><li><strong><a href="https://www.shodan.io/" target="_blank" rel="noreferrer">Shodan</a></strong> - Rechercher les services Internet indexés.</li><li><strong><a href="https://search.censys.io/" target="_blank" rel="noreferrer">Censys</a></strong> - Explorer les hôtes, certificats et services connus.</li><li><strong><a href="https://www.virustotal.com/" target="_blank" rel="noreferrer">VirusTotal</a></strong> - Recouper IP, domaines, URL et empreintes de fichiers.</li><li><strong><a href="https://urlscan.io/" target="_blank" rel="noreferrer">urlscan.io</a></strong> - Examiner les observations publiques de pages et URL.</li><li><strong><a href="https://www.abuseipdb.com/" target="_blank" rel="noreferrer">AbuseIPDB</a></strong> - Consulter les signalements associés à une adresse IP.</li><li><strong><a href="https://otx.alienvault.com/" target="_blank" rel="noreferrer">AlienVault OTX</a></strong> - Recouper des indicateurs de compromission.</li><li><strong><a href="https://urlhaus.abuse.ch/" target="_blank" rel="noreferrer">URLhaus</a></strong> - Rechercher des URL associées à la diffusion de malware.</li><li><strong><a href="https://threatfox.abuse.ch/" target="_blank" rel="noreferrer">ThreatFox</a></strong> - Examiner les indicateurs publics de menace.</li></ul><h2 id="archives-et-publications" tabindex="-1">Archives et publications <a class="header-anchor" href="#archives-et-publications" aria-label="Permalink to &quot;Archives et publications&quot;">​</a></h2><ul><li><strong><a href="https://web.archive.org/" target="_blank" rel="noreferrer">Wayback Machine</a></strong> - Voir les versions conservées d&#39;une page Web.</li><li><strong><a href="https://archive.org/" target="_blank" rel="noreferrer">Internet Archive</a></strong> - Rechercher des pages, documents et contenus archivés.</li><li><strong><a href="https://www.documentcloud.org/" target="_blank" rel="noreferrer">DocumentCloud</a></strong> - Explorer des documents publics et leurs annotations.</li><li><strong><a href="https://datasetsearch.research.google.com/" target="_blank" rel="noreferrer">Google Dataset Search</a></strong> - Retrouver des jeux de données publics.</li><li><strong><a href="https://github.com/search" target="_blank" rel="noreferrer">GitHub Search</a></strong> - Retrouver projets, dépôts et discussions indexés.</li></ul><h2 id="images-videos-et-geolocalisation" tabindex="-1">Images, vidéos et géolocalisation <a class="header-anchor" href="#images-videos-et-geolocalisation" aria-label="Permalink to &quot;Images, vidéos et géolocalisation&quot;">​</a></h2><ul><li><strong><a href="https://lens.google.com/" target="_blank" rel="noreferrer">Google Lens</a></strong> - Retrouver des images ressemblantes et éléments visuels.</li><li><strong><a href="https://tineye.com/" target="_blank" rel="noreferrer">TinEye</a></strong> - Rechercher les copies publiques d&#39;une image.</li><li><strong><a href="https://exiftool.org/" target="_blank" rel="noreferrer">ExifTool</a></strong> - Lire les métadonnées d&#39;images et de documents.</li><li><strong><a href="https://bellingcat.gitbook.io/toolkit" target="_blank" rel="noreferrer">Bellingcat Toolkit</a></strong> - Recouper lieux, médias et informations publiques.</li><li><strong><a href="https://earth.google.com/web/" target="_blank" rel="noreferrer">Google Earth</a></strong> - Comparer des vues de terrain et des repères géographiques.</li><li><strong><a href="https://www.openstreetmap.org/" target="_blank" rel="noreferrer">OpenStreetMap</a></strong> - Comparer rues, bâtiments et points d&#39;intérêt.</li></ul><h2 id="entreprises-et-registres" tabindex="-1">Entreprises et registres <a class="header-anchor" href="#entreprises-et-registres" aria-label="Permalink to &quot;Entreprises et registres&quot;">​</a></h2><ul><li><strong><a href="https://annuaire-entreprises.data.gouv.fr/" target="_blank" rel="noreferrer">Annuaire des entreprises</a></strong> - Vérifier les données des sociétés et établissements français.</li><li><strong><a href="https://opencorporates.com/" target="_blank" rel="noreferrer">OpenCorporates</a></strong> - Explorer les registres d&#39;entreprises de plusieurs pays.</li><li><strong><a href="https://www.pappers.fr/" target="_blank" rel="noreferrer">Pappers</a></strong> - Consulter les informations légales publiques d&#39;entreprises françaises.</li></ul><h2 id="methodes-rapports-et-referentiels" tabindex="-1">Méthodes, rapports et référentiels <a class="header-anchor" href="#methodes-rapports-et-referentiels" aria-label="Permalink to &quot;Méthodes, rapports et référentiels&quot;">​</a></h2><ul><li><strong><a href="https://github.com/jivoi/awesome-osint" target="_blank" rel="noreferrer">Awesome OSINT</a></strong> - Trouver une ressource complémentaire par domaine d&#39;investigation.</li><li><strong><a href="https://github.com/Jieyab89/OSINT-Cheat-sheet" target="_blank" rel="noreferrer">OSINT Cheat Sheet</a></strong> - Répertoire étendu de méthodes et d&#39;outils.</li><li><strong><a href="https://osintframework.com/" target="_blank" rel="noreferrer">OSINT Framework</a></strong> - Choisir un outil selon le type de renseignement.</li><li><strong><a href="https://gchq.github.io/CyberChef/" target="_blank" rel="noreferrer">CyberChef</a></strong> - Convertir et décoder des données.</li><li><strong><a href="https://attack.mitre.org/" target="_blank" rel="noreferrer">MITRE ATT&amp;CK</a></strong> - Relier des indices cyber aux techniques documentées.</li></ul><h2 id="methode-de-recherche" tabindex="-1">Méthode de recherche <a class="header-anchor" href="#methode-de-recherche" aria-label="Permalink to &quot;Méthode de recherche&quot;">​</a></h2><ol><li><strong>Définir</strong> la question, la cible et le périmètre.</li><li><strong>Collecter</strong> les informations publiques avec deux sources différentes.</li><li><strong>Recouper</strong> les identifiants, dates, domaines et relations sans conclure sur un seul indice.</li><li><strong>Conserver</strong> les URL, les dates UTC et les captures nécessaires au compte rendu.</li></ol><p>La disponibilité et les fonctionnalités de certains services varient selon leur formule. Une correspondance de pseudonyme ou de nom n&#39;est pas une preuve d&#39;identité.</p><p><strong><a href="./cheatsheet">Consulter les commandes OSINT</a></strong></p>',26)]))}const p=r(o,[["render",n]]);export{d as __pageData,p as default};
